/* OpenSSH ed25519 key files: a key generated by libssh must parse, ours must round-trip. */
#include "sshkey.h"
#include "crypto.h"
#include <stdio.h>
#include <string.h>
static int fails = 0;
#define CHECK(c) do { if (!(c)) { printf("SSHKEY TEST FAIL line %d: %s\n", __LINE__, #c); ++fails; } } while (0)
static const char SAMPLE[] = ""
    "-----BEGIN OPENSSH PRIVATE KEY-----\n"
    "\n"
    "-----END OPENSSH PRIVATE KEY-----\n";
static const char SAMPLE_PUB[] = "ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIJ842oR/9F4RdZaqjSMyap37plq8ITilmKa/9ztYZcHF\n";
int main()
{
    uint8_t seed[32], pub[32], chk[32]; char cm[80], line[200];
    CHECK(sshkey_parse_private((const uint8_t*)SAMPLE, sizeof(SAMPLE) - 1, seed, pub, cm, sizeof(cm)) == SSHKEY_OK);
    CHECK(ed25519_pubkey(seed, chk) == 0 && memcmp(chk, pub, 32) == 0);
    CHECK(sshkey_format_public(pub, "", line, sizeof(line)) > 0 && strcmp(line, SAMPLE_PUB) == 0);
    uint8_t p2[32]; CHECK(sshkey_parse_public(SAMPLE_PUB, p2) == 0 && memcmp(p2, pub, 32) == 0);
    CHECK(sshkey_parse_public("ssh-rsa AAAAB3NzaC1yc2EAAAADAQABAAAB", p2) != 0);
    char out[1200]; int n = sshkey_format_private(seed, pub, "user@rio", 0xCAFEBABEu, out, sizeof(out));
    CHECK(n > 100);
    uint8_t s3[32], p3[32]; CHECK(sshkey_parse_private((const uint8_t*)out, (uint32_t)n, s3, p3, cm, sizeof(cm)) == SSHKEY_OK && memcmp(s3, seed, 32) == 0 && memcmp(p3, pub, 32) == 0 && strcmp(cm, "user@rio") == 0);
    CHECK(sshkey_parse_private((const uint8_t*)"hello", 5, s3, p3, cm, sizeof(cm)) == SSHKEY_NOT_KEY);
    char bad[1200]; memcpy(bad, out, (size_t)n + 1); bad[60] ^= 1;                          /* damaged body */
    CHECK(sshkey_parse_private((const uint8_t*)bad, (uint32_t)n, s3, p3, cm, sizeof(cm)) != SSHKEY_OK);
    CHECK(sshkey_parse_private((const uint8_t*)out, (uint32_t)n - 40, s3, p3, cm, sizeof(cm)) != SSHKEY_OK);      /* truncated */
    if (!fails) puts("SSHKEY HOST TEST PASS");
    return fails ? 1 : 0;
}
